1	export type Item = {
2	  type: string;
3	};
4	
5	export type Step = {
6	  op: string;
7	  items: Item[];
8	};
9	
10	export type Customer = {
11	  yearsWithMHPCO: number;
12	};
13	
14	export type Scenario = {
15	  customer: Customer;
16	  steps: Step[];
17	};
18	
19	export type Result = {
20	  premium: number;
21	};
22	
23	export type ScenarioOutcome = {
24	  results: Result[];
25	};
26	
27	const PROCESSING_FEE = 5;
28	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
29	  sword: 100,
30	  amulet: 60,
31	  staff: 80,
32	  potion: 40,
33	  rune: 25,
34	  moonstone: 25,
35	};
36	
37	// Kept as an exact fraction rather than `amount * 1.1`, which drifts in
38	// floating point (100 * 1.1 === 110.00000000000001).
39	const withFirstInsuranceSurcharge = (amount: number): number =>
40	  (amount * 11) / 10;
41	
42	const BLOCK_SIZE = 3;
43	const BLOCK_BASE_PREMIUM = 60;
44	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
45	
46	const countByType = (items: Item[]): Map<string, number> => {
47	  const counts = new Map<string, number>();
48	  for (const item of items) {
49	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
50	  }
51	  return counts;
52	};
53	
54	// A group of exactly BLOCK_SIZE alike components forms a block and is charged
55	// a flat BLOCK_BASE_PREMIUM instead of the per-item price list rate. Main
56	// items never form a block.
57	const basePremiumForAlikeItems = (type: string, count: number): number =>
58	  COMPONENT_TYPES.has(type) && count === BLOCK_SIZE
59	    ? BLOCK_BASE_PREMIUM
60	    : count * BASE_PREMIUM_BY_TYPE[type];
61	
62	const policyBasePremiumOf = (items: Item[]): number =>
63	  [...countByType(items)].reduce(
64	    (total, [type, count]) => total + basePremiumForAlikeItems(type, count),
65	    0,
66	  );
67	
68	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
69	  const results = scenario.steps.map((step) => {
70	    const policyBasePremium = policyBasePremiumOf(step.items);
71	    const premium =
72	      withFirstInsuranceSurcharge(policyBasePremium) + PROCESSING_FEE;
73	    return { premium };
74	  });
75	
76	  return { results };
77	};
